import { attest } from "@arktype/attest"
import { type } from "arktype"
import { describe, it, expect } from "vitest"
import { Event, JsonValue, ParsedNumber, Role } from "../src/schemas.ts"

describe("ArkType schemas", () => {
	it("Role's inferred type is the literal-string union", () => {
		// Pure compile-time type-equality check using the `attest<T>(...)`
		// type-argument form. There is no chained assertion after the call;
		// ArkType's `setup()` records the assertion from the cached metadata
		// and checks the type relationship at test time.
		attest<"admin" | "user" | "guest">(Role.infer)
	})

	it("Role's inferred type serializes to the literal union", () => {
		// A `.type.toString.equals(...)` check on the type's serialized form
		// (the contract allows `.equals(...)` as an alternative to `.snap(...)`).
		attest(Role.infer).type.toString.equals('"admin" | "user" | "guest"')
	})

	it("Role rejects values that are not in the literal union", () => {
		// Runtime `.throws(...)` check on a thunk that should fail validation.
		attest(() => Role("not-a-role")).throws(/must be one of/)
	})

	it("ParsedNumber morphs numeric strings into numbers", () => {
		const out = ParsedNumber("42")
		expect(out).toBe(42)
		// Runtime equality check on the morph output.
		attest(ParsedNumber("42")).equals(42)
	})

	it("ParsedNumber rejects non-numeric strings", () => {
		// Runtime `.throws(...)` check on a morph that should fail validation.
		attest(() => ParsedNumber("not-a-number")).throws(/must be a number/)
	})

	it("JsonValue accepts nested structures", () => {
		const out = JsonValue({ a: [1, "x", null, { b: false }] })
		expect(out).toEqual({ a: [1, "x", null, { b: false }] })
		// Runtime equality check on the recursive-scope type's output.
		attest(out).snap({ a: [1, "x", null, { b: false }] })
	})

	it("Event accepts the discriminator-tagged 'login' branch", () => {
		const out = Event({ kind: "login" })
		expect(out).toEqual({ kind: "login" })
		// Runtime equality check on the discriminated-union's inferred output.
		attest(out).equals({ kind: "login" })
	})

	it("Event rejects an unknown discriminator tag", () => {
		// Runtime `.throws(...)` check on the discriminated union failing.
		attest(() => Event({ kind: "weird" })).throws(/must be "login" or "logout"/)
	})

	it("Throws-and-has-type-error on an invalid arktype DSL expression", () => {
		// `// @ts-expect-error` is required because `% 0` is an arktype DSL
		// error surfaced at the TypeScript level (via `type.validate<...>`).
		// The thunk also throws at runtime, so we exercise the combined check.
		// @ts-expect-error
		attest(() => type("number%0")).throwsAndHasTypeError(
			"% operator must be followed by a non-zero integer literal (was 0)"
		)
